// request guards
import { Request } from './types';

export function guardUser(req: Request): boolean {
  return !!req.user;
}

export function guardOrg(req: Request): boolean {
  return !!req.org;
}

export function guardScope(req: Request): boolean {
  return !!req.scope;
}

export function isRateLimited(req: Request): boolean {
  return req.hits > 100;
}

export function isRateLimitedBurst(req: Request): boolean {
  return req.burst > 20;
}

files.src/types.ts:
export interface Request {
  user?: string;
  org?: string;
  scope?: string;
  hits: number;
  burst: number;
}

files.src/server.ts:
import { isRateLimited } from './guards';

// isRateLimited decides on 429
export function handle(req: any) {
  if (isRateLimited(req)) return 429;
  return 200;
}

